                        const newHead1_2 = {
                            x: head1.x + direction1.x,
                            y: head1.y + direction1.y
                        };
                        if (newHead1_2.x < 0 || newHead1_2.x >= GRID_SIZE || newHead1_2.y < 0 || newHead1_2.y >= GRID_SIZE) {
                            showGameOver();
                            return;
                        }
                    }

                    // Self collision for snake2
                    for (const segment of snake2) {
                        if (newHead2.x === segment.x && newHead2.y === segment.y) {
                            // Check if snake1 also died
                            const head1 = snake1[snake1.length - 1];
                            const newHead1_2 = {
                                x: head1.x + direction1.x,
                                y: head1.y + direction1.y
                            };
                            if (newHead1_2.x === segment.x && newHead1_2.y === segment.y) {
                                showGameOver();
                                return;
                            }
                            showGameOver();
                            return;
                        }
                    }

                    // Opponent collision for snake2
                    if (currentMode === 'cpu-vs-human') {
                        for (const segment of snake1) {
                            if (newHead2.x === segment.x && newHead2.y === segment.y) {
                                showGameOver();
                                return;
                            }
                        }
                    }

                    // Food collision for snake2
                    if (checkFoodCollision(snake2)) {
                        snake2.push({ ...newHead2 });
                        score++;
                        scoreElement.textContent = score;
                        placeFood();
                    } else {
                        snake2.push({ ...newHead2 });
                        snake2.shift();
                    }
                }

                drawGame();
            }, 150);
        }

        // Draw game
        function drawGame() {
            // Clear canvas
            ctx.fillStyle = '#0a0a0f';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            // Draw grid
            ctx.strokeStyle = '#1a1a24';
            ctx.lineWidth = 1;
            for (let i = 0; i <= GRID_SIZE; i++) {
                ctx.beginPath();
                ctx.moveTo(i * CELL_SIZE, 0);
                ctx.lineTo(i * CELL_SIZE, canvas.height);
                ctx.stroke();
                ctx.beginPath();
                ctx.moveTo(0, i * CELL_SIZE);
                ctx.lineTo(canvas.width, i * CELL_SIZE);
                ctx.stroke();
            }

            // Draw food
            if (food) {
                ctx.fillStyle = '#ff4444';
                ctx.beginPath();
                const centerX = food.x * CELL_SIZE + CELL_SIZE / 2;
                const centerY = food.y * CELL_SIZE + CELL_SIZE / 2;
                const radius = CELL_SIZE / 3;
                ctx.arc(centerX, centerY, radius, 0, Math.PI * 2);
                ctx.fill();
            }

            // Draw snake1
            for (let i = 0; i < snake1.length; i++) {
                const segment = snake1[i];
                const x = segment.x * CELL_SIZE;
                const y = segment.y * CELL_SIZE;

                if (i === snake1.length - 1) {
                    // Head
                    ctx.fillStyle = segment.color;
                    ctx.beginPath();
                    ctx.roundRect(x + 2, y + 2, CELL_SIZE - 4, CELL_SIZE - 4, 4);
                    ctx.fill();

                    // Eyes
                    ctx.fillStyle = '#000';
                    const eyeSize = 3;
                    if (direction1.x === 1) {
                        ctx.fillRect(x + CELL_SIZE - 5, y + 5, eyeSize, eyeSize);
                        ctx.fillRect(x + CELL_SIZE - 5, y + CELL_SIZE - 8, eyeSize, eyeSize);
                    } else if (direction1.x === -1) {
                        ctx.fillRect(x + 2, y + 5, eyeSize, eyeSize);
                        ctx.fillRect(x + 2, y + CELL_SIZE - 8, eyeSize, eyeSize);
                    } else if (direction1.y === -1) {
                        ctx.fillRect(x + 5, y + 2, eyeSize, eyeSize);
                        ctx.fillRect(x + CELL_SIZE - 8, y + 2, eyeSize, eyeSize);
                    } else {
                        ctx.fillRect(x + 5, y + CELL_SIZE - 5, eyeSize, eyeSize);
                        ctx.fillRect(x + CELL_SIZE - 8, y + CELL_SIZE - 5, eyeSize, eyeSize);
                    }
                } else {
                    // Body
                    ctx.fillStyle = segment.color;
                    ctx.beginPath();
                    ctx.roundRect(x + 2, y + 2, CELL_SIZE - 4, CELL_SIZE - 4, 3);
                    ctx.fill();
                }
            }

            // Draw snake2
            for (let i = 0; i < snake2.length; i++) {
                const segment = snake2[i];
                const x = segment.x * CELL_SIZE;
                const y = segment.y * CELL_SIZE;

                if (i === snake2.length - 1) {
                    // Head
                    ctx.fillStyle = segment.color;
                    ctx.beginPath();
                    ctx.roundRect(x + 2, y + 2, CELL_SIZE - 4, CELL_SIZE - 4, 4);
                    ctx.fill();

                    // Eyes
                    ctx.fillStyle = '#000';
                    const eyeSize = 3;
                    if (direction2.x === 1) {
                        ctx.fillRect(x + CELL_SIZE - 5, y + 5, eyeSize, eyeSize);
                        ctx.fillRect(x + CELL_SIZE - 5, y + CELL_SIZE - 8, eyeSize, eyeSize);
                    } else if (direction2.x === -1) {
                        ctx.fillRect(x + 2, y + 5, eyeSize, eyeSize);
                        ctx.fillRect(x + 2, y + CELL_SIZE - 8, eyeSize, eyeSize);
                    } else if (direction2.y === -1) {
                        ctx.fillRect(x + 5, y + 2, eyeSize, eyeSize);
                        ctx.fillRect(x + CELL_SIZE - 8, y + 2, eyeSize, eyeSize);
                    } else {
                        ctx.fillRect(x + 5, y + CELL_SIZE - 5, eyeSize, eyeSize);
                        ctx.fillRect(x + CELL_SIZE - 8, y + CELL_SIZE - 5, eyeSize, eyeSize);
                    }
                } else {
                    // Body
                    ctx.fillStyle = segment.color;
                    ctx.beginPath();
                    ctx.roundRect(x + 2, y + 2, CELL_SIZE - 4, CELL_SIZE - 4, 3);
                    ctx.fill();
                }
            }
        }

        // Initial draw
        drawGame();
    </script>
